import{_ as e,o as s,c as n,a2 as i}from"./chunks/framework.DpbdyYUv.js";const h=JSON.parse('{"title":"Zigbee con la UNIT Pulsar ESP32-C6","description":"","frontmatter":{},"headers":[],"relativePath":"guide/zigbee.md","filePath":"guide/zigbee.md"}'),t={name:"guide/zigbee.md"};function o(r,a,l,p,d,c){return s(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="zigbee-con-la-unit-pulsar-esp32-c6" tabindex="-1">Zigbee con la UNIT Pulsar ESP32-C6 <a class="header-anchor" href="#zigbee-con-la-unit-pulsar-esp32-c6" aria-label="Permalink to &quot;Zigbee con la UNIT Pulsar ESP32-C6&quot;">​</a></h1><h2 id="_1-introduccion" tabindex="-1">1. Introducción <a class="header-anchor" href="#_1-introduccion" aria-label="Permalink to &quot;1. Introducción&quot;">​</a></h2><p>Zigbee es un protocolo de comunicación inalámbrica de bajo consumo basado en el estándar <strong>IEEE 802.15.4.</strong> Está diseñado principalmente para aplicaciones de IoT, automatización, sensores y dispositivos embebidos que requieren comunicación inalámbrica con bajo consumo energético y la posibilidad de formar redes con múltiples dispositivos.</p><p>A diferencia de tecnologías como <strong>Wi-Fi</strong>, Zigbee está orientado a transmitir pequeñas cantidades de información y permite crear redes con topologías estrella, árbol y malla.</p><p>En este tutorial revisaremos el protocolo <strong>Zigbee</strong> utilizando empleando dos entornos de desarrollo:</p><ul><li>Arduino IDE.</li><li>Espressif ESP-IDF.</li></ul><p>El objetivo es comprender desde los conceptos fundamentales de Zigbee hasta la comunicación entre múltiples dispositivos ESP32-C6.</p><h2 id="_2-esp32-c6-y-zigbee" tabindex="-1">2. ESP32-C6 y Zigbee <a class="header-anchor" href="#_2-esp32-c6-y-zigbee" aria-label="Permalink to &quot;2. ESP32-C6 y Zigbee&quot;">​</a></h2><p>El ESP32-C6 tiene soporte para IEEE 802.15.4 permite utilizar tecnologías como:</p><ul><li>Zigbee.</li><li>Thread.</li></ul><p>Esto hace que el ESP32-C6 pueda utilizarse directamente como nodo Zigbee sin necesidad de agregar un transceptor Zigbee externo.</p><h2 id="_3-conceptos-fundamentales" tabindex="-1">3. Conceptos fundamentales <a class="header-anchor" href="#_3-conceptos-fundamentales" aria-label="Permalink to &quot;3. Conceptos fundamentales&quot;">​</a></h2><p>Es importante comprender algunos conceptos utilizados dentro de una red Zigbee.</p><h3 id="_3-1-coordinator" tabindex="-1">3.1 Coordinator <a class="header-anchor" href="#_3-1-coordinator" aria-label="Permalink to &quot;3.1 Coordinator&quot;">​</a></h3><p>El Coordinator es el dispositivo encargado de crear la red Zigbee.</p><p>En una red solamente puede existir un Coordinator.</p><p>Sus principales funciones son:</p><ul><li>Crear la red.</li><li>Seleccionar el canal Zigbee.</li><li>Asignar parámetros de red.</li><li>Permitir que otros dispositivos se unan.</li><li>Inicializar la estructura de la red.</li></ul><h3 id="_3-2-router" tabindex="-1">3.2 Router <a class="header-anchor" href="#_3-2-router" aria-label="Permalink to &quot;3.2 Router&quot;">​</a></h3><p>Un Router puede comunicarse con otros dispositivos y además retransmitir mensajes.</p><p>Esto permite extender el alcance de la red.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Coordinator</span></span>
<span class="line"><span>     │</span></span>
<span class="line"><span>     │</span></span>
<span class="line"><span>   Router</span></span>
<span class="line"><span>   /    \\</span></span>
<span class="line"><span>Node    Node</span></span></code></pre></div><h3 id="_3-3-end-device" tabindex="-1">3.3 End Device <a class="header-anchor" href="#_3-3-end-device" aria-label="Permalink to &quot;3.3 End Device&quot;">​</a></h3><p>Un End Device representa normalmente un dispositivo final como:</p><ul><li>Sensor.</li><li>Interruptor.</li><li>Actuador.</li><li>Medidor.</li><li>Dispositivo alimentado por batería.</li></ul><p>Los End Devices no retransmiten paquetes de otros dispositivos.</p><h3 id="_3-4-endpoints" tabindex="-1">3.4 Endpoints <a class="header-anchor" href="#_3-4-endpoints" aria-label="Permalink to &quot;3.4 Endpoints&quot;">​</a></h3><p>Un Endpoint puede entenderse como una interfaz lógica dentro de un dispositivo Zigbee.</p><p>Por ejemplo:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ESP32-C6</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── Endpoint 1</span></span>
<span class="line"><span>│   └── Sensor de temperatura</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── Endpoint 2</span></span>
<span class="line"><span>│   └── Interruptor</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└── Endpoint 3</span></span>
<span class="line"><span>    └── Sensor ADC</span></span></code></pre></div><p>Un mismo ESP32-C6 puede implementar varios dispositivos lógicos utilizando diferentes Endpoints.</p><h3 id="_3-5-clusters" tabindex="-1">3.5 Clusters <a class="header-anchor" href="#_3-5-clusters" aria-label="Permalink to &quot;3.5 Clusters&quot;">​</a></h3><p>Los Clusters agrupan funcionalidades relacionadas.</p><p>Algunos ejemplos son:</p><table tabindex="0"><thead><tr><th>Cluster</th><th>Función</th></tr></thead><tbody><tr><td>Basic</td><td>Información básica del dispositivo</td></tr><tr><td>Identify</td><td>Identificación</td></tr><tr><td>On/Off</td><td>Encendido y apagado</td></tr><tr><td>Temperature Measurement</td><td>Temperatura</td></tr><tr><td>Analog Input</td><td>Entrada analógica</td></tr></tbody></table><h2 id="_4-redes" tabindex="-1">4. Redes <a class="header-anchor" href="#_4-redes" aria-label="Permalink to &quot;4. Redes&quot;">​</a></h2><p>Zigbee permite diferentes formas de organizar los dispositivos.</p><h3 id="_4-1-estrella" tabindex="-1">4.1 Estrella <a class="header-anchor" href="#_4-1-estrella" aria-label="Permalink to &quot;4.1 Estrella&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>       End Device</span></span>
<span class="line"><span>           │</span></span>
<span class="line"><span>           │</span></span>
<span class="line"><span>End ── Coordinator ── End</span></span>
<span class="line"><span>           │</span></span>
<span class="line"><span>           │</span></span>
<span class="line"><span>       End Device</span></span></code></pre></div><p>Todos los dispositivos se comunican directamente con el Coordinator.</p><h3 id="_4-2-arbol" tabindex="-1">4.2 Árbol <a class="header-anchor" href="#_4-2-arbol" aria-label="Permalink to &quot;4.2 Árbol&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>          Coordinator</span></span>
<span class="line"><span>          /         \\</span></span>
<span class="line"><span>      Router       Router</span></span>
<span class="line"><span>      /   \\         /   \\</span></span>
<span class="line"><span>    End   End     End   End</span></span></code></pre></div><h3 id="_4-3-malla" tabindex="-1">4.3 Malla <a class="header-anchor" href="#_4-3-malla" aria-label="Permalink to &quot;4.3 Malla&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        Coordinator</span></span>
<span class="line"><span>        /         \\</span></span>
<span class="line"><span>    Router ───── Router</span></span>
<span class="line"><span>      │   \\       / │</span></span>
<span class="line"><span>      │    \\     /  │</span></span>
<span class="line"><span>     End    Router   End</span></span></code></pre></div><p>La topología de malla permite que existan diferentes rutas para transportar la información.</p><h2 id="_5-primeros-pasos" tabindex="-1">5. Primeros pasos <a class="header-anchor" href="#_5-primeros-pasos" aria-label="Permalink to &quot;5. Primeros pasos&quot;">​</a></h2><p>Para este ejemplo crearemos un <strong>coordinator</strong> y un <strong>end device</strong>.</p><h4 id="requisitos" tabindex="-1">Requisitos <a class="header-anchor" href="#requisitos" aria-label="Permalink to &quot;Requisitos&quot;">​</a></h4><ol><li>Dos UNIT Pulsar ESP32-C6.</li><li>Un cable USB para cada ESP32-C6.</li></ol><h3 id="arduino-ide" tabindex="-1">Arduino IDE <a class="header-anchor" href="#arduino-ide" aria-label="Permalink to &quot;Arduino IDE&quot;">​</a></h3><p>Arduino permite realizar una implementación más sencilla y abstrae gran parte de la configuración interna del stack Zigbee.</p><h3 id="esp-idf" tabindex="-1">ESP-IDF <a class="header-anchor" href="#esp-idf" aria-label="Permalink to &quot;ESP-IDF&quot;">​</a></h3><p>ESP-IDF permite trabajar directamente con las herramientas oficiales de Espressif y proporciona mayor control sobre:</p>`,53)])])}const m=e(t,[["render",o]]);export{h as __pageData,m as default};
